/// <reference path="../pb_data/types.d.ts" />
// Steady - the patient's daily start (psychologists' own words of encouragement) and fictional
// demo patients for the RADR research view.
// SPDX-License-Identifier: AGPL-3.0-or-later
//
//  quotes      : short sentences a psychologist adds to the daily start screen of their own
//                patients, alongside the ones built into the app.
//  users.demo  : a made-up patient generated by deploy/accounts.sh demo-patients. Demo accounts
//                can't sign in (random password) and are removed with --remove.

const RESEARCH_GUARD = "@request.auth.active = true && @request.auth.mustChangePassword = false";
const RESEARCH_TWO_STEP = " && (@request.auth.role = 'patient' || @request.auth.totpEnabledAt != '')";
const DEMO_LOCK = " && @request.body.demo:isset = false";

migrate((app) => {
  const users = app.findCollectionByNameOrId("users");
  users.fields.add(new BoolField({ name: "demo" }));
  const rule = users.updateRule === null || users.updateRule === undefined ? null : String(users.updateRule);
  if (rule && rule.indexOf("@request.body.demo:") < 0) users.updateRule = rule + DEMO_LOCK;
  app.save(users);

  const guard = RESEARCH_GUARD + ($os.getenv("STEADY_REQUIRE_2FA") !== "off" ? RESEARCH_TWO_STEP : "");
  const quotes = new Collection({
    type: "base",
    name: "quotes",
    fields: [
      { name: "text", type: "text", required: true, min: 3, max: 240 },
      { name: "author", type: "text", max: 80 },
      { name: "active", type: "bool" },
      { name: "createdBy", type: "relation", collectionId: users.id, maxSelect: 1, required: true, cascadeDelete: true },
      { name: "created", type: "autodate", onCreate: true, onUpdate: false },
      { name: "updated", type: "autodate", onCreate: true, onUpdate: true }
    ],
    // a psychologist's own, and for patients, their own psychologist's
    listRule: guard + " && (createdBy = @request.auth.id || (createdBy = @request.auth.clinician && active = true))",
    viewRule: guard + " && (createdBy = @request.auth.id || (createdBy = @request.auth.clinician && active = true))",
    createRule: guard + " && @request.auth.role = 'clinician' && @request.body.createdBy = @request.auth.id",
    updateRule: guard + " && createdBy = @request.auth.id && @request.body.createdBy:isset = false",
    deleteRule: guard + " && createdBy = @request.auth.id"
  });
  app.save(quotes);
}, (app) => {
  try { app.delete(app.findCollectionByNameOrId("quotes")); } catch (_) { /* gone */ }
  const users = app.findCollectionByNameOrId("users");
  users.fields.removeByName("demo");
  if (users.updateRule) users.updateRule = String(users.updateRule).replace(DEMO_LOCK, "");
  app.save(users);
});
